INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3815, 'publish'::public.course_status, 'agile-foundations', 'Agile Foundations', '
<h3 id="h-learning-objectives">Learning objectives</h3>



<ul><li>Recognize inhibitors that have a significant impact when managing an agile team.</li><li>Define the “agile manifesto.”</li><li>Recall the structure of a cross-functional team.</li><li>Determine what should be included in user stories.</li><li>Apply the 80/20 rule to determine the priority of highest value items.</li><li>List two agile principles that guide the team to stay within time structures while remaining flexible enough to adapt to change.</li><li>Name a disadvantage of the waterfall approach.</li></ul>



<p><strong>Skills covered</strong></p>



<ul><li>Agile Project Management</li><li>Agile Methodologies</li></ul>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">Teams that embrace an agile mindset are often better able to respond to customer feedback and shifting business needs—and have a bit more fun in the process. Interested in bringing the principles of agile to your team? This course can help. Join Doug Rose as he steps through the fundamental concepts you need to know to start thinking like an agile team. Doug goes over the values and principles covered in the agile manifesto, as well as how to enhance communication with user stories and cross-functional teams. Discover how to respond to change the agile way, explore popular agile frameworks, and learn about the common roles on an agile team. Along the way, Doug provides you with some exercises that can help boost your team''s agility and productivity.</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, NULL, TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3750, NULL, '/courses/3815/', '/courses/3815', '2022-02-22 11:30:40'::timestamptz, '2022-07-27 02:27:51'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3801, 'publish'::public.course_status, 'arianna-huffington-discovering-meditation-and-sleep', 'Arianna Huffington: Discovering Meditation and Sleep', '
<p>The former president and editor-in-chief of The Huffington Post Media Group, knows a thing or two about having a very busy schedule, has taken on the role of sleep evangelist after realizing the lack of proper rest is taking a toll on peoples’ health, job performance, relationships and overall happiness. Huffington calls it a sleep deprivation crisis that she only woke up to after exhaustion sent her to the hospital.</p>



<p>Live a life filled with less stress, greater well-being, and enhanced productivity by learning how to make transformational changes. Start your Thrive journey and discover how to go from coping and surviving to actually thriving. In this first course of a six-course series, Arianna Huffington discusses the benefits of meditation and sleep in this first course of six.</p>



<h3 id="h-learning-objectives">Learning objectives</h3>



<ul><li>Starting your Thrive journey for transformational change</li><li>Auditing your life and making goals</li><li>Creating a life tracker</li><li>Understanding the role of sleep</li><li>Meditating</li><li>Rethinking how to live life</li></ul>



<p><strong>Course Length</strong>: 57min</p>



<p><strong>Course Materials</strong>: Provided</p>



<ul><li><a href="https://drive.google.com/uc?export=download&amp;id=1tHd9X379o7zHCfN6_KGOIH3XNTPufQXK" target="_blank" rel="noreferrer noopener">Ex_Files_Arianna_Huffington_Thrive_01.zip</a></li></ul>



<p><strong>Note</strong>: Courses are not visible on mobile devices at this time</p>



<h3 id="h-would-you-like-to-donate-to-the-luthas-center-for-excellence">Would you like to donate to the Luthas Center for Excellence?</h3>



<img alt="" border="0" src="https://www.paypal.com/en_US/i/scr/pixel.gif" width="1" height="1">

', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">
<div class="row no-gutters d-flex flex-column justify-content-center align-items-center">
<div class="row d-flex justify-content-center mc-mt-1">
<p class="col-12 col-md-8 col-lg-7">The former president and editor-in-chief of The Huffington Post Media Group, who knows a thing or two about having a very busy schedule, has taken on the role of sleep evangelist after realizing the lack of proper rest is taking a toll on peoples’ health, job performance, relationships and overall happiness. Huffington calls it a sleep deprivation crisis that she only woke up to after exhaustion sent her to the hospital.</p>
</div>
</div>
</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, NULL, TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3743, NULL, '/courses/3801/', '/courses/3801', '2022-02-27 14:45:40'::timestamptz, '2022-07-27 02:27:50'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3835, 'pending'::public.course_status, 'artificial-intelligence', 'Artificial Intelligence', '
<p>In computer science, artificial intelligence (AI), sometimes called machine intelligence, is intelligence demonstrated by machines, in contrast to the natural intelligence displayed by humans. Colloquially, the term "artificial intelligence" is often used to describe machines (or computers) that mimic "cognitive" functions that humans associate with the human mind, such as "learning" and "problem-solving".</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:10:56'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3769, 'publish'::public.course_status, 'aws-certified-cloud-practitioner-training', 'AWS Certified Cloud Practitioner Training', '
<p>We guarantee you that this is the most comprehensive and up-to-date online resource to learn AWS and prepare for the AWS Cloud Practitioner certification exam. You will learn everything you need to ace the exam, become an AWS Certified Cloud Practitioner, and gain the skills you need to get hired in 2022!</p>



<h3>This course includes:</h3>



<ul><li>Access to the exclusive Luthas Center community</li><li>Exclusive AWS Cloud Practitioner practice exam and quizzes</li><li>Unlimited access to all courses, workshops, career paths and resources</li></ul>



<p><strong>Instructor(s)</strong>: Amber Israelsen<br><strong>Class Length</strong>: 7 hrs of video<br><strong>Category</strong>: Technical Certifications, AWS<br><strong>Course Materials</strong>: 35+ bonus resources + 1 project<br><strong>Link to Course</strong>: AWS Certified Cloud Practitioner Training</p>



<h3>COURSE PREVIEW </h3>


<!-- wp:embed {"url":"https://www.youtube.com/embed/QHXoFX52xUQ","type":"rich","providerNameSlug":"embed-handler","responsive":true,"className":"wp-embed-aspect-16-9 wp-has-aspect-ratio"} -->
<figure class="wp-block-embed is-type-rich is-provider-embed-handler wp-block-embed-embed-handler wp-embed-aspect-16-9 wp-has-aspect-ratio"><div class="wp-block-embed__wrapper">
https://www.youtube.com/embed/QHXoFX52xUQ
</div></figure>



<div style="height:30px" aria-hidden="true" class="wp-block-spacer"></div>



<div class="wp-block-group">
<h3 class="has-text-align-center">Donate to the Luthas Center </h3>



<div class="wp-block-buttons">
<div class="wp-block-button"><a class="wp-block-button__link" href="https://cash.app/$DameLuthas">CashApp</a></div>



<div class="wp-block-button"><a class="wp-block-button__link" href="https://www.paypal.com/donate/?hosted_button_id=KV3MZ7EJ8Y5SW">Paypal</a></div>



<div class="wp-block-button"><a class="wp-block-button__link" href="https://account.venmo.com/u/DameLuthas" target="_blank" rel="noreferrer noopener">Venmo</a></div>
</div>
</div>



<div style="height:30px" aria-hidden="true" class="wp-block-spacer"></div>



<p>This AWS Cloud Practitioner course covers all new information and best practices for 2022 and is focused on efficiency.<br></p>



<p><strong>That means you''ll never have to spend time on confusing, out-of-date, incomplete tutorials anymore.</strong><br></p>



<p>Instead we''re laser-focused on teaching you&nbsp;<em>exactly</em>&nbsp;what you need to ace the AWS Certified Cloud Practitioner exam so that you can learn AWS, get certified, and get hired.<br></p>



<p>And this course goes beyond just teaching you the information, it''ll also ensure you get across the finish line.<br></p>



<p>You''ll get&nbsp;<strong>study strategies, tips, demos, practice questions, and a full practice exam</strong>&nbsp;from your instructor. Your instructor has passed the certification&nbsp;<em>multiple times</em>&nbsp;simply to ensure she''s providing you the most up-to-date, accurate information and study strategies for the exam.<br></p>



<p><strong>Now&nbsp;<em>that''s</em>&nbsp;dedication.</strong><br></p>



<p>And the success stories speak for themselves.<br></p>



<p>Graduates are now working at Google, Tesla, Amazon, Apple, IBM, Uber, Facebook, Shopify + other top tech companies.<br></p>



<p>They are also working as top freelancers getting paid while working remotely around the world.<br></p>



<p><strong>This can be you.</strong><br></p>



<p>By enrolling today, you’ll also get to join our exclusive live&nbsp;online community classroom&nbsp;to learn alongside thousands of students, alumni, mentors, TAs and Instructors.<br></p>



<p>Most importantly, you will learn from a senior industry professional that has actual real-world experience working with and teaching AWS.</p>



<h3 id="h-why-should-i-learn-aws">Why Should I Learn AWS?​</h3>



<p>We like you already. Asking those smart, tough questions!<br></p>



<p>Becoming an AWS Certified Cloud Practitioner is a great way to pivot into tech or take your existing career in tech to the next level. That''s because it provides you with some seriously lucrative opportunities.<br></p>



<p>There are&nbsp;<a href="https://www.linkedin.com/jobs/search/?keywords=aws" target="_blank" rel="noreferrer noopener">240,000+ job postings</a>&nbsp;available in the United States for those with AWS skills, and the average salary of an AWS Cloud Engineer is over&nbsp;<a href="https://www.glassdoor.ca/Salaries/us-aws-engineer-salary-SRCH_IL.0,2_IN1_KO3,15.htm" target="_blank" rel="noreferrer noopener">$100,000 / year</a>.<br></p>



<p>Plus AWS is huge. Like, really huge. AWS has about&nbsp;<strong>75%</strong>&nbsp;of the share of the enterprise cloud market. It''s the biggest player in a&nbsp;<a href="https://www.prnewswire.com/news-releases/cloud-computing-market-size-worth-1251-09-billion-by-2028--cagr-19-1-grand-view-research-inc-301366888.html" target="_blank" rel="noreferrer noopener">trillion dollar market</a>. So we''ll say it again: it''s HUGE.<br></p>



<p>If all that doesn''t boggle your mind then call a doctor.<br></p>



<p><strong>Key takeaway?</strong>&nbsp;AWS is a highly lucrative skill for which companies are desperately trying to hire people.<br>That''s before we even talk about the fact that more and more companies are implementing and utilizing cloud services every day. This is only the beginning. And that means you have definitely not missed the boat.<br></p>



<p>Getting into this space now will give you a future-proof career.<br></p>



<p>With your AWS Cloud Practitioner certification you''ll be well positioned to work with and help companies that use AWS cloud services. But even better, it also opens the door for you to work in more advanced roles where you can earn even higher salaries.<br></p>



<p>As you can see, this career has tons of potential, but you still need to grab it by the horns. You still need to seize the opportunity. So seize it!</p>



<h3 id="h-here-s-what-this-aws-cloud-practitioner-course-covers">Here''s what this AWS Cloud Practitioner course covers:​</h3>



<p>This course, like all Luthas Center Mastery courses, will be constantly updated as the landscape changes.</p>



<p><br>As the AWS ecosystem evolves this course will also be continually updated with new lectures and resources. This will be your go-to place to find the latest AWS Cloud best practices and resources anytime in the future.<br></p>



<p><strong>1. AWS CLOUD FUNDAMENTALS</strong>&nbsp;- You''re going to learn AWS from scratch. That means starting with fundamental questions like: what is the cloud and what is the problem that it solves?<br></p>



<p>Plus you''ll learn exactly what makes AWS so powerful and popular, including security, elasticity, scalability, global reach, and the economics of AWS.<br></p>



<p>You''ll soon be able to explain to anyone exactly why AWS specifically, and cloud technologies generally, are so prevalent now and so important for the future.<br></p>



<p>But that''s not all. From the very first section of this course you''re going to learn about cloud architecture design principles. This is the stuff that companies will pay you the big bucks for knowing, so we think it should be a foundational part of your learning journey.<br></p>



<p>And of course there are demos and practice questions for you along the way.<br></p>



<p><strong>2. SECURITY &amp; COMPLIANCE</strong>&nbsp;- As an AWS guru, you will wield great power. And of course, with great power comes great responsibility.<br></p>



<p>You will control and secure a fundamental aspect of your company''s business: its cloud services and the protection of information, identities, applications, and devices.<br></p>



<p>So you''ll be learning how to master tools and concepts that will allow you to confidently manage security and compliance, including AWS Identity and Access Management (IAM), Security Hub, Secrets Manager, and encryption on AWS.<br></p>



<p><strong>3. TECHNOLOGY &amp; INFRASTRUCTURE</strong>&nbsp;- The goal of this course is to prepare you to ace the AWS Cloud Practitioner certification exam as efficiently and effectively as possible.<br></p>



<p>That means you need to attain a deep understanding of the many AWS technologies you''ll encounter as an AWS Cloud Engineer.<br></p>



<p>So that''s exactly what we''ll do.<br></p>



<p>You''ll learn everything you need to know about cloud deployment models, EC2 Instances, S3 Storage Classes, Virtual Private Cloud, analytics, databases, containers, monitoring, application integration, and developer tools like CodeBuild, CodeStar, and CodeDeploy.<br></p>



<p>And you''ll learn exactly how to work with these technologies through the AWS Management Console, Command Line Interface (CLI), and programmatically.<br></p>



<p>Sounds like a lot? It is. But we couldn''t be more confident that you can do this.<br></p>



<p><strong>Because your instructor Amber makes everything crystal clear and she keeps the lessons laser-focused on what you need to ace the certification</strong>.<br></p>



<p>Plus any time you''re stuck or have your questions, you''ll be able to ask Amber and fellow students within the private Discord community... 24/7.<br></p>



<p><strong>4. BILLING &amp; PRICINGS</strong>&nbsp;- As the cloud guru at your new job you need to know AWS from top-to-bottom, including AWS pricing models, billing tools, and account structures.<br></p>



<p>Sure it may not sound like the most exciting information, but it''s a key part of the AWS Cloud Practitioner certification exam, so you need to understand it just as well as any other piece.<br></p>



<p><strong>5. AWS PRACTICE EXAM, STUDY TIPS, QUIZZES + MORE</strong>&nbsp;- You''re here to get certified and launch your new career as an AWS Cloud Engineer.<br></p>



<p>To do that you need to pass the certification exam. That''s what you''re here for. That''s what this is all about.<br></p>



<p>And we don''t take that lightly.<br></p>



<p><strong>That''s why this course doesn''t just throw information at you and then leave you hanging in the wind like so many other courses and tutorials.</strong><br></p>



<p>Hell no!<br></p>



<p>This course will help you get over the finish line by walking through the exam guide with you and providing you with&nbsp;<strong>study strategies, tips, whitepapers, FAQs, practice questions, and a full, randomized, 65-question, Cloud Practitioner practice exam</strong>.<br></p>



<p>By the time you take the exam, you''ll be completely ready.<br></p>



<p>You''ll even see how to register for the exam. We like to make things easy for you, y''know?</p>



<h3 id="h-what-s-the-bottom-line">What''s the bottom line?​</h3>



<p>This course is not about making you just follow along so that when you are done with the course you don’t know what to do other than watch another tutorial.</p>
', '<p>Learn AWS from scratch, from an industry expert. You''ll learn AWS fundamentals all the way to advanced cloud technologies, so that you''ll be able to ace the certification exam and get hired as a Cloud Engineer!</p>', NULL, 'open', NULL, 'open', NULL, 'https://www.youtube.com/watch?v=QHXoFX52xUQ', TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3726, NULL, '/courses/3769/', '/courses/3769', '2022-04-10 07:57:29'::timestamptz, '2022-07-27 02:27:48'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3829, 'pending'::public.course_status, 'aztec-empire', 'Aztec Empire', '
<p>The Aztec Empire, or the Triple Alliance, was an alliance of three Nahua altepetl city-states: Mexico-Tenochtitlan, Texcoco, and Tlacopan. These three city-states ruled the area in and around the Valley of Mexico from 1428 until the combined forces of the Spanish conquistadores and their native allies under Hernán Cortés slaughtered them in 1521.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:34:45'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3819, 'publish'::public.course_status, 'communicating-with-emotional-intelligence', 'Communicating with Emotional Intelligence', '
<p>Developing your emotional intelligence can help you succeed at any stage of your life or career. It can also help you become a better leader, mentor, and coach. In this course, Brenda Bailey-Hughes defines exactly what emotional intelligence is and how it can help you manage your emotions and build stronger relationships. Learn how to understand others’ perspectives, balance empathy and accountability, demonstrate listening, and respond appropriately to a variety of verbal and nonverbal cues. Using these simple techniques, you can quickly improve your communication and make conversations at work and home more productive and satisfying.</p>


<!-- wp:wpcp/useyourdrive-block {"shortcode":""} /-->


<p></p>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">
<div>Developing your emotional intelligence can help you succeed at any stage of your life or career. It can also help you become a better leader, mentor, and coach. In this course, Brenda Bailey-Hughes defines exactly what emotional intelligence is and how it can help you manage your emotions and build stronger relationships. Learn how to understand others’ perspectives, balance empathy and accountability, demonstrate listening, and respond appropriately to a variety of verbal and nonverbal cues. Using these simple techniques, you can quickly improve your communication and make conversations at work and home more productive and satisfying.</div>
</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, 'https://bit.ly/3sUORDY', FALSE, 0, 'lesson_course_id_fallback', '{"lessons":5,"topics":0,"quizzes":0}'::jsonb, 3752, NULL, '/courses/3819/', '/courses/3819', '2022-02-18 18:08:12'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3837, 'pending'::public.course_status, 'concepts-of-computer-engineering', 'Concepts of Computer Engineering', '
<p>Computer engineering is a branch of engineering that integrates several fields of computer science and electronics engineering required to develop computer hardware and software. Computer engineers usually have training in electronic engineering (or electrical engineering), software design, and hardware-software integration instead of only software engineering or electronic engineering. Computer engineers are involved in many hardware and software aspects of computing, from the design of individual microcontrollers, microprocessors, personal computers, and supercomputers, to circuit design. This field of engineering not only focuses on how computer systems themselves work but also how they integrate into the larger picture.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:09:32'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3845, 'pending'::public.course_status, 'contacting-small-business-owners', 'Contacting Small Business Owners', '
<p>There are three different situations you’ll find yourself talking to a small business owner in: on the phone, through email, or in person. Each situation offers its own respective challenges and benefits, but they also all share the common goal of inciting the owner to do something for you.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 01:55:40'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3825, 'pending'::public.course_status, 'cosmology-and-astronomy', 'Cosmology and Astronomy', '
<p>Cosmology is a branch of astronomy that involves the origin and evolution of the universe, from the Big Bang to today and on into the future. According to NASA, the definition of cosmology is "the scientific study of the large scale properties of the universe as a whole."</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:40:14'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3851, 'pending'::public.course_status, 'create-an-eco-friendly-house', 'Create an Eco-Friendly House', '
<p>Green, sustainable, energy-efficient…there is so many ways to say “eco-friendly” that it can feel overwhelming to consider making some environmentally friendly changes. Creating an eco-friendly home can start small, with just a few easy steps. As you save money, you can move into bigger changes to save even more. You may be surprised to learn that saving the planet can also save your wallet!</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-20 22:45:17'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3813, 'publish'::public.course_status, 'creating-a-video-resume', 'Creating a Video Resume', '
<p>In this course, Madeline Mann helps you explore the untapped possibilities of a video resume. Find out more about the value of video as a resume format and why it’s quickly becoming a new norm. Learn how to plan, film, edit, submit, and feature your video resume. Work with Madeline to develop an action plan and commit to it in your job-hunting process.</p>



<p><strong>Course Length</strong>: 23m</p>



<p><strong>Course Materials</strong>: <a href="https://drive.google.com/uc?export=download&amp;id=1CTds-Qm2JDfxfZDah7Xxg0gF_gts2D6w" target="_blank" rel="noreferrer noopener">Ex_Files_Creating_a_Video_Resume.zip</a></p>



<p> </p>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">Next time you''re looking to capture the attention of a company you want to work for, consider creating a video resume. Video resumes are becoming more accepted by many companies, and yet it''s still an approach that very few job seekers fully embrace. Companies like Zappos have optional video submissions, and TikTok even created its own resume platform that allows candidates to submit TikTok resumes to companies who are hiring. Employers seem to be embracing video more than ever before, using it during the interview process for video applications, one-way interviews, and video interviews with prospective employees.</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, NULL, TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3749, NULL, '/courses/3813/', '/courses/3813', '2022-02-22 16:55:26'::timestamptz, '2022-07-27 02:27:51'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3853, 'pending'::public.course_status, 'cybersecurity-standards', 'Cybersecurity Standards', '
<p>Cybersecurity standards (also styled cybersecurity standards) are techniques generally set forth in published materials that attempt to protect the cyber environment of a user or organization. This environment includes users themselves, networks, devices, all software, processes, the information in storage or transit, applications, services, and systems that can be connected directly or indirectly to networks.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-19 10:39:18'::timestamptz, '2022-07-27 02:27:54'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3817, 'publish'::public.course_status, 'financial-wellness-managing-personal-cash-flow', 'Financial Wellness: Managing Personal Cash Flow', '
<h3 id="h-learning-objectives">Learning objectives</h3>



<ul><li>Identify the various meanings money has to people.</li><li>Describe strategies for overcoming financial frustrations.</li><li>Differentiate the ways in which human bodies handle stress.</li><li>Define the factors in the 3S cash flow model.</li><li>Relate actions to a successful method of managing cash flow.</li></ul>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">
<div>Developing your emotional intelligence can help you succeed at any stage of your life or career. It can also help you become a better leader, mentor, and coach. In this course, Brenda Bailey-Hughes defines exactly what emotional intelligence is and how it can help you manage your emotions and build stronger relationships. Learn how to understand others’ perspectives, balance empathy and accountability, demonstrate listening, and respond appropriately to a variety of verbal and nonverbal cues. Using these simple techniques, you can quickly improve your communication and make conversations at work and home more productive and satisfying.</div>
</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, 'https://bit.ly/3sUORDY', FALSE, 0, 'lesson_course_id_fallback', '{"lessons":2,"topics":0,"quizzes":0}'::jsonb, 3751, NULL, '/courses/3817/', '/courses/3817', '2022-02-22 11:26:07'::timestamptz, '2022-07-27 02:27:51'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3839, 'pending'::public.course_status, 'get-cash-for-your-annuity', 'Get Cash for Your Annuity', '
<p>An annuity is a type of investment that is usually handled by an insurance company. An investor will invest her money in an annuity fund in exchange for periodic payouts over a predetermined interval (such as for the next ten years) or indefinitely (for the rest of your life). Some annuities provide the option of getting immediate payment. However, if you are in a financial emergency and require immediate cash, you might have to cash out an annuity early. While there may be hefty fees involved, particularly if your annuity is held within a retirement account like an IRA or 401k, it is possible to get immediate cash from your annuity investment.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:06:31'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3841, 'pending'::public.course_status, 'home-gardening-safety', 'Home Gardening Safety', '
<p>Gardening can be a fulfilling hobby, but there are many ways your skin can get irritated while you’re working. Plants could cause skin irritation, the sun could cause burns, and bugs can spread harmful bacteria or cause itchiness. When you’re gardening, wearing protective clothing and gloves, putting on sunscreen, and applying bug repellent can all help you stay safe while you’re outside!</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:02:42'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3849, 'pending'::public.course_status, 'how-to-fundraise', 'How to Fundraise', '
<p>There''s no question that charities, nonprofits, PTAs, clubs, and many other groups need to raise funds. The question is, how to do it effectively. This article introduces several ways that your group can raise funds for its projects.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, 2265, '/courses//', '/courses/', '2020-04-21 01:48:46'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3847, 'pending'::public.course_status, 'how-to-prepare-for-a-drought', 'How to Prepare for a Drought', '
<p>Droughts are prolonged periods of less-than-average rainfall. They can last from several weeks to years, causing significant hardship due to lack of water for drinking, cleaning, and watering crops. If you live in a drought-prone area, it will help if you take a few measures to ensure that you and your community are as prepared as possible if a drought hits.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 01:52:44'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3797, 'publish'::public.course_status, 'learn-emotional-intelligence-the-key-determiner-of-success', 'Learn Emotional Intelligence, the Key Determiner of Success', '
<p>Learn how to become more mindful of your strengths, limitations, and the values that define them; explore ways to create space between yourself, your thoughts, and your emotions; develop awareness of how people see the world differently based on individual preferences, as well as social and environmental factors; and use awareness of self and others to work toward collaboration, innovation, and mutually beneficial relationships</p>



<p><strong>Course Length</strong>: 32min</p>



<p><strong>Course Transcript</strong>: Provided</p>



<ul><li>Transcript: <a href="/transcript-learn-emotional-intelligence-the-key-determiner-of-success-course">Learn Emotional Intelligence, the Key Determiner of Success</a></li></ul>



<p><strong>Course Materials</strong>: Provided</p>



<ul><li>Google Drive Download: <a href="https://drive.google.com/uc?export=download&amp;id=1UwmWLpBFDe7Wep_Oi0fwpeeMxfj3LOsK" target="_blank" rel="noreferrer noopener">Ex_Files_Learn_Emotional_Intelligence.zip</a></li></ul>



<p><strong>Note</strong>: Courses are not visible on mobile devices at this time</p>



<h3 id="h-would-you-like-to-donate-to-the-luthas-center-for-excellence">Would you like to donate to the Luthas Center for Excellence?</h3>



<img alt="" border="0" src="https://www.paypal.com/en_US/i/scr/pixel.gif" width="1" height="1">

', '<p>Explore the four domains of emotional intelligence—self-awareness, self-management, social awareness, and relationship management—as defined by psychologist and author Daniel Goleman</p>', NULL, 'open', NULL, 'open', NULL, NULL, TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3741, NULL, '/courses/3797/', '/courses/3797', '2022-02-28 00:29:48'::timestamptz, '2022-07-27 02:27:50'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3823, 'pending'::public.course_status, 'machine-learning-foundations-a-case-study-approach', 'Machine Learning Foundations: A Case Study Approach', '
<p>In this course, you will get hands-on experience with machine learning from a series of practical case-studies. At the end of the first course you will have studied how to predict house prices based on house-level features, analyze sentiment from user reviews, retrieve documents of interest, recommend products, and search for images. Through hands-on practice with these use cases, you will be able to apply machine learning methods in a wide range of domains.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'lesson_course_id_fallback', '{"lessons":3,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:42:32'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3807, 'publish'::public.course_status, 'masterclass-alicia-keys-teaches-songwriting-and-producing', 'Masterclass: Alicia Keys Teaches Songwriting and Producing', '
<p>With 15 Grammy Awards and more than 40 million albums sold so far, Alicia Keys is one of the world’s most beloved singer-songwriters. Now the legendary artist invites you into her studio to share her process for creating music built from authentic emotion. Breaking down anthems like “Fallin’,” Alicia shows you how she writes lyrics, crafts melodies, and explores sonics so you can discover the music you were born to make.</p>



<p><strong>Instructor(s)</strong>: Alicia Keys<br><strong>Class Length</strong>: 19 video lessons (3 hrs 22 min)<br><strong>Category</strong>: Music<br><strong>Course Materials</strong>: <a href="https://drive.google.com/uc?export=download&amp;id=1ZUz6cKpAMASxM-qgdPi7KjrpkSnll63a" target="_blank" rel="noreferrer noopener">Class Workbook.pdf</a></p>



<p>Note: Courses are not visible on mobile devices at this time</p>



<h3 id="h-would-you-like-to-donate-to-the-luthas-center-for-excellence">Would you like to donate to the Luthas Center for Excellence?</h3>



<img alt="" border="0" src="https://www.paypal.com/en_US/i/scr/pixel.gif" width="1" height="1">




<p>Lesson Plan</p>



<ol><li>Meet Your Instructor<br>03:58<br>Alicia introduces herself and invites you to join her in the spaces where she pursues her artistry.</li><li>Alicia’s Musical Foundation and Influences<br>06:16<br>Learn the who, what, where, and why of Alicia’s inspiration.</li><li>Start With Melody and Lyrics<br>09:52<br>Alicia shares her methods and styles for developing lyrics.</li><li>Alicia, the Songwriter<br>09:48<br>Alicia talks about journaling, writing poetry, and drawing from your life to create.</li><li>Bring All the Elements Together<br>12:53<br>Alicia explains how “Fallin'' ” came together and the intricacies of the songwriting process.</li><li>Connect to the World Around You<br>10:46<br>Discover Alicia’s approach to using connection as a way to hone your creative voice.</li><li>Songwriting With Empathy<br>18:40<br>Alicia demonstrates how she uses empathy to create powerful music.</li><li>Alicia, the Producer<br>10:33<br>Take a look inside Alicia’s sound booth as she discusses the roles she takes on to produce her distinct sound.</li><li>Vocal Arrangements<br>13:27<br>Alicia walks you through the strength in specific vocal arrangements.</li><li>Build Energy in the Booth<br>14:10<br>Alicia opens up about how she has developed physical, mental, and emotional practices to take care of herself and her art.</li><li>The Anatomy of an Anthem<br>07:45<br>Alicia shares her thoughts on what makes a song an anthem, and talks about the theme and tone of the “sad triumph.”</li><li>Alicia’s Retro-Futuristic Sound<br>08:21<br>Alicia explains how various influences have helped her develop her incredible sound.</li><li>Alchemy in the Control Room<br>10:57<br>Learn how Alicia explores her creativity through sonics and instruments in the control room.</li><li>Instruments to Boost a Big Sound<br>14:11<br>Discover Alicia’s favorite instruments and her methods for achieving her unique musical sounds.</li><li>Creative Collaboration<br>09:29<br>Alicia talks about the importance of collaboration and the role it can play in her creative process.</li><li>Sisterhood in the Music Industry<br>06:57<br>Alicia discusses discrepancies in the music industry for women and her efforts to create space at the table for voices that are silenced.</li><li>Rising Artist Spotlight: Joy Nesbitt’s “Echo”<br>18:36<br>Alicia offers advice to a young artist from her music organization, She Is the Music.</li><li>Power and Purpose<br>10:38<br>Discover Alicia’s personal philosophy of setting boundaries and listening to your body and intuition.</li><li>Always Be Learning<br>05:42<br>Alicia shares her thoughts on living a creative life and why evolution is the only constant.</li></ol>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">
<div class="row no-gutters d-flex flex-column justify-content-center align-items-center">
<div class="row d-flex justify-content-center mc-mt-1">
<p class="col-12 col-md-8 col-lg-7">With 15 Grammy Awards and more than 40 million albums sold so far, Alicia Keys is one of the world’s most beloved singer-songwriters. Now the legendary artist invites you into her studio to share her process for creating music built from authentic emotion</p>
</div>
</div>
</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, 'https://www.youtube-nocookie.com/embed/PbeaQXYW7DY', TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3746, NULL, '/courses/3807/', '/courses/3807', '2022-02-26 09:24:51'::timestamptz, '2022-07-27 02:27:51'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3779, 'publish'::public.course_status, 'masterclass-bob-iger-teaches-strategy-and-leadership', 'Masterclass: Bob Iger Teaches Strategy and Leadership', '
<p>In an era of disruption, former <strong>Disney</strong> CEO Bob Iger led one of the world’s most beloved brands to unprecedented success with the acquisitions of <strong>Pixar, Marvel, and Lucasfilm</strong>. Now, through case studies and lessons from 45 years in media, Bob teaches you how to evolve your business and career. Learn strategies for expanding a brand, leading with integrity, and making big moves—from risk management to the art of negotiation.</p>



<p><strong>Instructor(s)</strong>: Bob Iger<br><strong>Class Length</strong>: 13 video lessons (2 hrs 11 min)<br><strong>Category</strong>: Business<br><strong>Course Materials</strong>:  <a href="https://drive.google.com/uc?export=download&amp;id=1SwlpM23JEb2hTrQKyz9FFxl3C5KeBzhW" target="_blank" rel="noreferrer noopener">Class Workbook.pdf</a></p>



<p><strong>Course Lessons:</strong></p>



<ol><li>Introduction<br>04:53<br>Meet your new instructor: former CEO of The Walt Disney Company, Bob Iger. In his introduction, Bob talks about what he’s learned from great teachers and what he wants to share with you.</li><li>Using Your Time Effectively<br>6:10<br>To demonstrate how to use your time effectively, Bob shares in detail how he structures his day to make the most of it. He talks about making time for focus and reveals just how early he wakes up.</li><li>Focus, Strategy &amp; Priorities<br>8:51<br>Bob believes you must narrow your focus to develop a successful strategy. He illustrates this point by explaining how he ultimately convinced the Disney board that he should become the next CEO.</li><li>Taking Giant Swings: Pixar Acquisition Case Study<br>24:55<br>Bob breaks down the acquisition of Pixar, including his strategy to convince Steve Jobs—the head of Pixar—and the Disney board. He explains how he overcame the odds with the acquisition and why it was essential to Disney’s future success.</li><li>The Art of Negotiation<br>4:43<br>Bob shares his tips for successful negotiation, including how to remove your ego from the process and how to make everyone feel like they’ve come out a winner.</li><li>Creating Brand Value<br>15:10<br>It goes without saying that the Disney brand is powerful. Bob explains why the brand needed to evolve while staying true to its core in order to stay relevant.</li><li>Expanding Your Brand: Marvel Acquisition Case Study<br>6:39<br>Bob shares the strategy behind folding Marvel into the Disney brand, and he discusses how to capitalize on well-loved brands to maximize growth.</li><li>Anticipating What Consumers Want<br>9:10<br>Bob gives his perspective on consumer data and why he believes you sometimes have to push it aside and go with your gut. He uses the films Black Panther and Captain Marvel to illustrate his point.</li><li>The Importance of Risk-Taking<br>9:05<br>Bob shares why he thinks taking risks is essential to success, even when they end in failure. He uses an example from early in his career when he made an epic mistake that ultimately yielded a huge success.</li><li>Navigating Complex Deals: 21st Century Fox Case Study<br>14:24<br>The process to acquire 21st Century Fox was complicated and time-consuming. Bob walks you through the deal and explains the challenges.</li><li>Managing Industry Disruption: Disney Plus Case Study<br>8:52<br>One of Bob’s superpowers is his ability to predict where the industry is headed. He talks about how Disney navigated the change to streaming video on demand, starting with ESPN+ and leading to Disney+.</li><li>Tenets for Success<br>16:36<br>Bob shares his tenets for successful leadership, including how to foster curiosity, practice candor, project optimism, be authentic, and own your mistakes.</li><li>Conclusion<br>01:58<br>To conclude, Bob wishes students the best on their future, encouraging them to lead with integrity and advocate for a better world.</li></ol>
', '<p>Former Disney CEO Bob Iger teaches you the leadership skills and strategies he used to reimagine one of the world’s most beloved brands.</p>', NULL, 'open', NULL, 'open', NULL, 'https://youtu.be/G8j0w5E_ZTc', TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3732, NULL, '/courses/3779/', '/courses/3779', '2022-03-15 17:59:09'::timestamptz, '2022-07-27 02:27:49'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3803, 'publish'::public.course_status, 'masterclass-bobbi-brown-teaches-makeup-and-beauty', 'Masterclass: Bobbi Brown Teaches Makeup and Beauty', '
<p>Bobbi Brown’s philosophy is that makeup should be quick and natural, and it should enhance who you are. A beauty industry icon, Bobbi shares her expertise in step-by-step tutorials, using models with a range of skin tones. You’ll learn how to choose the right foundation, do a smoky eye and a statement lip, and take your look from day to night. But most of all, you’ll learn how to feel confident in your own skin.</p>



<p><strong>Course Length</strong>: 3hrs 48min</p>



<p><strong>Course Materials</strong>: Provided</p>



<ul><li><a href="https://drive.google.com/uc?export=download&amp;id=1squFzUWBuIUB7vJVfJIiCy3TxE3tmlV8" target="_blank" rel="noreferrer noopener">Class Workbook.pdf</a></li></ul>



<p><strong>Note</strong>: Courses are not visible on mobile devices at this time</p>



<h3 id="h-would-you-like-to-donate-to-the-luthas-center-for-excellence">Would you like to donate to the Luthas Center for Excellence?</h3>



<img alt="" border="0" src="https://www.paypal.com/en_US/i/scr/pixel.gif" width="1" height="1">




<p><strong>Lesson Plan</strong></p>



<ol><li>Bobbi’s Beauty Philosophy<br>06:32<br>Bobbi shares her beauty philosophy: Makeup should be quick and natural, and it should enhance who you are. She explains what her class will cover and why she’ll be demonstrating on models of different ages and with a range of skin tones.</li><li>The Changing Face of Beauty<br>7:37<br>While makeup has been around for ages, styles are constantly changing. Bobbi discusses makeup from the 1960s to today. She talks about the origin of Bobbi Brown Cosmetics and how the face of beauty has changed through the “It” girls of the times.</li><li>Color and Makeup<br>8:38<br>Color is critical: It can make a statement and reveal your individuality. Bobbi discusses how color and style are key to self-expression and how undertones can help you find the right colors. She also clears up a misconception about nude makeup.</li><li>Inside Bobbi’s Makeup Kit<br>7:14<br>Bobbi shares the essential items in her day bag, her evening bag, and her travel bag. You’ll learn how to simplify your makeup collection and carry only the essentials for different moments of your day and life.</li><li>Foundation<br>31:18<br>Demonstrating on models with different skin tones, Bobbi shows you techniques for applying your foundation.</li><li>Using Tinted Moisturizer<br>5:04<br>When you don’t need a full face of foundation, you can use a tinted moisturizer instead. Demonstrating on a medium skin tone, Bobbi applies tinted moisturizer and shows how you can then use your foundation and concealer for touch-ups, creating a spotless look with a healthy glow.</li><li>Bronzer and Blush<br>24:02<br>These are Bobbi’s favorite products because they can make you look great when you’re not feeling your best. Bobbi applies bronzer and blush to three models and discusses the tools, techniques, and products used.</li><li>Eyes and Brows<br>26:57<br>Bobbi demonstrates how to play up your eyes and correctly fill in your brows. You’ll learn Bobbi’s tips and tricks for the eye and brow area, including which mascara color is the only one you should use.</li><li>Creating a Statement Lip<br>8:56<br>Demonstrating with a dark matte color, Bobbi applies a statement lip on a model and shares how you can do it, too. This application works for a classic red, a bright pink, or darker and more unforgiving colors.</li><li>Skincare Essentials<br>13:26<br>Bobbi breaks down today’s skincare products, from makeup removers to moisturizers, and explains which products are essential for healthy skin.</li><li>Workplace Makeup<br>8:59<br>As an entrepreneur and CEO, Bobbi knows how to play up her features for the workplace while still looking professional. She’ll show you how to apply a workplace-appropriate look, depending on the type of office you work in.</li><li>Self-Application: Day to Night<br>12:56<br>So you can learn to be your own best makeup artist, Bobbi talks a model through how to apply her own makeup, emphasizing how to choose the right colors.</li><li>The Perfect Smoky Eye<br>17:20<br>The smoky eye is a technique that can easily go wrong. Bobbi shows you how to apply a simple, modern smoky eye and then shows how you can play it up.</li><li>1-Minute Makeup<br>2:49<br>As a working artist and businesswoman, Bobbi knows how important it is to be able to do your makeup in just about a minute. She demonstrates a quick and easy look that uses only a few products.</li><li>Makeup Mistakes<br>7:19<br>Bobbi discusses some common makeup mistakes—including using too light of a foundation and washing out the color of your lips—and does a live demonstration of how to fix them.</li><li>For Aspiring Makeup Artists<br>11:27<br>Bobbi shares personal stories and lessons from her career as a makeup artist.</li><li>Editorial Makeup<br>18:03<br>Bobbi shows you how to experiment with bold colors and not be afraid to make mistakes or take a look too far.</li><li>Conclusion<br>02:08<br>Bobbi shares lessons from her decades in the beauty industry: Be on time, ask for help, and do the most you can for others. She believes in the power of hard work and determination and urges you to not give up on your passions and goals.</li><li>Bonus: Bobbi’s Business Philosophy<br>8:04<br>Bobbi discusses the business of beauty and offers advice for aspiring leaders. She shares lessons from her time in the boardroom, from building a team to giving a business time to grow.</li></ol>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">
<div class="row no-gutters d-flex flex-column justify-content-center align-items-center">
<div class="row d-flex justify-content-center mc-mt-1">
<p class="col-12 col-md-8 col-lg-7">Bobbi Brown’s philosophy is that makeup should be quick and natural, and it should enhance who you are. A beauty industry icon, Bobbi shares her expertise in step-by-step tutorials, using models with a range of skin tones.</p>
</div>
</div>
</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, 'https://www.youtube-nocookie.com/embed/_IY-YVJliA4', TRUE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3744, NULL, '/courses/3803/', '/courses/3803', '2022-02-26 20:13:51'::timestamptz, '2022-07-27 02:27:51'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
