INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3821, 'pending'::public.course_status, 'mba-in-a-box', 'MBA in a Box', '
<p>MBA in a box is a collection of the five courses that are most frequently taught to MBA students. We have carried out extensive research and explored the curriculums of the most successful MBA programs around the world including Harvard Business School, Wharton School of the University of Pennsylvania, INSEAD, Booth School of Business, London Business School and others. This is the reason the following modules have been included in this program:  </p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'lesson_course_id_fallback', '{"lessons":4,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 03:11:23'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3843, 'pending'::public.course_status, 'pack-furniture-for-moving', 'Pack Furniture for Moving', '
<p>Moving can be exciting, but it can also feel like an overwhelming amount of work. Packing your furniture is one of the biggest components of any move. If you gather the right materials and wrap your pieces carefully, you can make sure they survive the move in great shape. Just make sure to break down larger items before packing, if possible. You''ll also want to take extra care with fragile items by using extra layers of protection.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 01:57:51'::timestamptz, '2022-07-27 02:27:53'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3831, 'pending'::public.course_status, 'pangaea-the-first-continent', 'Pangaea: The First Continent', '
<p>Pangaea or Pangea was a supercontinent that existed during the late Paleozoic and early Mesozoic eras. It assembled from earlier continental units approximately 335 million years ago, and it began to break apart about 175 million years ago. In contrast to the present Earth and its distribution of continental mass, much of Pangaea was in the Southern Hemisphere and surrounded by a superocean, Panthalassa. Pangaea was the most recent supercontinent to have existed and the first to be reconstructed by geologists.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:32:12'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3811, 'publish'::public.course_status, 'supporting-your-mental-health-while-working-from-home', 'Supporting Your Mental Health While Working from Home', '
<p>In this course, neuroscience expert and author Amy Brann helps you adjust to this new normal by training your brain to overcome disruptions and distractions, accept and get real about your emotions, reframe your expectations, and preserve your relationships. Using the latest insights from neuroscience, Amy shares nontechnical, practical guidance for not just surviving, but thriving as you work from home.</p>
', '<div class="ember-view classroom-layout-panel-layout-main__module">
<div class="classroom-workspace-overview__description t-16">Working from home is a new phenomenon for many professionals. Different worlds—work, school, and parenting—are suddenly colliding. People are discovering how much their environment impacts their productivity and wellbeing, and how difficult it can be to focus when there are so many demands on their time.</div>
</div>
<div class="ember-view classroom-layout-panel-layout-main__module"> </div>', NULL, 'open', NULL, 'open', NULL, NULL, FALSE, 0, 'lesson_course_id_fallback', '{"lessons":1,"topics":0,"quizzes":0}'::jsonb, 3748, NULL, '/courses/3811/', '/courses/3811', '2022-02-23 16:41:48'::timestamptz, '2022-07-27 02:27:51'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3833, 'pending'::public.course_status, 'the-american-frontier', 'The American Frontier', '
<p>The American frontier comprises the geography, history, folklore, and cultural expression of life in the forward wave of American expansion that began with English colonial settlements in the early 17th century and ended with the admission of the last remaining western territories as states in 1959. This era of massive migration and settlement was particularly encouraged by President Thomas Jefferson following the Louisiana Purchase, giving rise to the expansionist philosophy known as "manifest destiny".</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, NULL, '/courses//', '/courses/', '2020-04-21 02:12:32'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.courses (wp_id, status, slug, title, content, excerpt, short_description, price_type, price, access_mode, certificate_id, intro_video, materials_enabled, menu_order, steps_source, step_counts, featured_image_id, cover_image_id, old_path, new_path, published_at, modified_at) VALUES (3827, 'pending'::public.course_status, 'the-french-revolution', 'The French Revolution', '
<p>The French Revolution was a period of far-reaching social and political upheaval in France and its colonies beginning in 1789. The Revolution overthrew the monarchy, established a republic, catalyzed violent periods of political turmoil, and finally culminated in a dictatorship under Napoleon who brought many of its principles to areas he conquered in Western Europe and beyond.</p>
', '', NULL, 'open', NULL, 'open', 0, NULL, FALSE, 0, 'none', '{"lessons":0,"topics":0,"quizzes":0}'::jsonb, NULL, 2339, '/courses//', '/courses/', '2020-04-21 02:37:32'::timestamptz, '2022-07-27 02:27:52'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET status = EXCLUDED.status, slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, short_description = EXCLUDED.short_description, price_type = EXCLUDED.price_type, price = EXCLUDED.price, access_mode = EXCLUDED.access_mode, certificate_id = EXCLUDED.certificate_id, intro_video = EXCLUDED.intro_video, materials_enabled = EXCLUDED.materials_enabled, menu_order = EXCLUDED.menu_order, steps_source = EXCLUDED.steps_source, step_counts = EXCLUDED.step_counts, featured_image_id = EXCLUDED.featured_image_id, cover_image_id = EXCLUDED.cover_image_id, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;

