INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17367, 'the-school-of-obstacles-and-adversity-2', 'Mastermind', ' ', 'From One Comes Many. Find those who disagree and provide them with the strategies and tools that will help them understand our Narrative.', 'publish'::public.post_status, 1, 17464, NULL, '/the-school-of-obstacles-and-adversity-2/', '/blog/the-school-of-obstacles-and-adversity-2', '2023-04-19 08:02:18'::timestamptz, '2023-04-19 08:02:18'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17368, 'the-school-of-obstacles-and-adversity-3', 'Lady Strategist', ' ', 'Definition of Excellence. Empower the people who know there''s something more to life, as well as those who need guidance to improve their Quality of Life', 'publish'::public.post_status, 1, 17463, NULL, '/the-school-of-obstacles-and-adversity-3/', '/blog/the-school-of-obstacles-and-adversity-3', '2023-04-19 08:02:18'::timestamptz, '2023-04-19 08:02:18'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17355, 'you-heal-i-heal-we-heal', 'You Heal, I Heal, We Heal', ' ', 'You Heal, I Heal, We Heal program – for Domestic Abuse survivors, Recovering addicts, Coma survivors, Grief counselors are all aligned and committed to purpose.', 'publish'::public.post_status, 1, 17472, NULL, '/you-heal-i-heal-we-heal/', '/blog/you-heal-i-heal-we-heal', '2023-04-19 07:43:54'::timestamptz, '2023-04-19 07:43:54'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17356, 'mental-health-services', 'Mental Health services', 'At the Luthas Center for Excellence, we believe that mental wellness is the cornerstone of a fulfilling life. Our Mental Health Services Program is designed to empower women and children by providing them with the tools and resources they need to navigate life’s challenges. Situated in New York and Atlanta, we offer a sanctuary where individuals can come to understand and heal their minds, supported by a community that genuinely cares.
<h4>Our Services</h4>
<ul>
 	<li><strong>Counseling Services</strong>: Our licensed mental health professionals offer one-on-one counseling, family counseling, and group therapy sessions.</li>
 	<li><strong>Educational Workshops</strong>: We provide workshops on stress management, coping mechanisms, emotional intelligence, and other vital mental health topics.</li>
 	<li><strong>Wellness Activities</strong>: From mindfulness meditation to art therapy, our variety of wellness activities aim to engage the mind, body, and soul.</li>
 	<li><strong>Resource Center</strong>: An extensive collection of books, articles, and online resources are available to help individuals educate themselves about mental health.</li>
 	<li><strong>Telehealth Services</strong>: For those who can''t make it in person, we offer virtual consultations and therapy sessions.</li>
</ul>
<h4>Our Impact</h4>
We have already helped hundreds of women and children overcome adversity, grow stronger mentally, and create a brighter future for themselves. We aim to be a catalyst for change, advocating for mental health at both the community and policy levels.
<h4>How You Can Help</h4>
<ul>
 	<li><strong>Donate</strong>: Your financial contributions enable us to provide subsidized services to those who can''t afford them.</li>
 	<li><strong>Volunteer</strong>: From administrative tasks to facilitating workshops, your time and skills can make a difference.</li>
 	<li><strong>Spread the Word</strong>: Help us create a larger impact by sharing our mission and services with your network.</li>
</ul>
<h4>Contact Us</h4>
For more information about our Mental Health Services Program or to schedule an appointment, please visit our website or contact us directly.', 'Mental Health Survivor Programs – with emphasis on PTSD, Anxiety & ADHD', 'publish'::public.post_status, 1, 18082, NULL, '/mental-health-services/', '/blog/mental-health-services', '2023-04-19 07:43:54'::timestamptz, '2023-09-19 16:29:55'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17357, 'the-school-of-obstacles-and-adversity', 'The School of Obstacles and Adversity', 'The School of Obstacles and Adversity is not a physical institution with brick walls and chalkboards; rather, it''s an abstract concept that represents the life experiences that test our mettle, challenge our beliefs, and push us to our limits. Unlike traditional schools, it doesn''t have a set curriculum, fixed timetable, or standardized tests. The lessons are tailor-made for each individual, drawing from the unique adversities they face. In this school, failure is not a mark of shame but a stepping stone to growth. The ultimate aim is to build resilience, foster emotional intelligence, and equip individuals with the skills needed to navigate life''s complexities.
<h2>Why the School of Obstacles and Adversity Matters</h2>
<ol>
 	<li><strong>Teaches Resilience</strong>: In a world that''s ever-changing and full of uncertainties, resilience is not just a useful skill but a necessary one. It''s the ability to bounce back from setbacks and adapt to change that sets you apart.</li>
 	<li><strong>Builds Emotional Intelligence</strong>: The emotional rigors of overcoming obstacles provide an opportunity to understand oneself and others better, which is the cornerstone of emotional intelligence.</li>
 	<li><strong>Fosters Self-Reliance</strong>: As you navigate through challenges, you learn to rely on your own abilities, reinforcing self-reliance and independence.</li>
 	<li><strong>Instills a Growth Mindset</strong>: Confronting adversity head-on shifts your perspective from a fixed mindset ("I can''t do this") to a growth mindset ("I can learn to do this").</li>
</ol>
<h2>The Curriculum</h2>
<h3>Lesson 1: Failure as Feedback</h3>
Learn to see failure not as a dead end but as valuable feedback that provides insights into areas for improvement.
<h3>Lesson 2: Adaptability Over Rigidity</h3>
Adaptability is the skill of the future. Being rigid in your approaches can be a downfall; learning to adapt ensures you''re always ready for what life throws at you.
<h3>Lesson 3: Emotional Mastery</h3>
Understanding your emotional triggers and how to manage them will not only help you in difficult times but also enhance your relationships and overall mental well-being.
<h3>Lesson 4: The Power of Perspective</h3>
Changing your perspective can change your experience. Learn how to reframe obstacles as opportunities for growth.
<h2>Real-World Applications</h2>
<ol>
 	<li><strong>Overcoming Adversity</strong>: Those who graduate from this school are better equipped to handle life''s challenges, from personal hardships to professional setbacks.</li>
 	<li><strong>Relationship Building</strong>: Emotional intelligence gained from overcoming obstacles aids in forming and sustaining meaningful relationships.</li>
 	<li><strong>Career Advancement</strong>: The skills learned are transferable and highly valued in the professional world, providing a competitive edge in the job market.</li>
</ol>
<h2>Conclusion</h2>
The School of Obstacles and Adversity is a lifelong learning journey that everyone is enrolled in, whether they realize it or not. It doesn''t provide a diploma or a formal degree, but the skills and lessons you acquire are invaluable assets that contribute to personal and professional success. In this school, you''re both the student and the teacher, constantly learning from your experiences and imparting wisdom onto others. After all, life''s most meaningful lessons are often learned not in the classroom but in the quiet struggle against adversity.', 'The School of Obstacles and Adversity is not your typical educational institution. It''s an ongoing, life-long journey where each challenge serves as a lesson in resilience, emotional intelligence, and personal growth. In this abstract classroom, you''ll learn to navigate life''s complexities, build meaningful relationships, and acquire invaluable skills that traditional education often overlooks.', 'publish'::public.post_status, 1, 18086, NULL, '/the-school-of-obstacles-and-adversity/', '/blog/the-school-of-obstacles-and-adversity', '2023-04-19 07:43:54'::timestamptz, '2023-09-19 18:39:42'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17349, 'homeless-prevention', 'HavenCycle: Prevent, Survive, Thrive', '<h1>HavenCycle: A Lifeline in Every Phase of Homelessness</h1>
<h2>Introduction:</h2>
Welcome to HavenCycle, a groundbreaking initiative by the <a href="https://www.luthascenterforexcellence.org">Luthas Center for Excellence</a> designed to support you through every stage of homelessness: from prevention to survival and onto a path of stability. Our mission is to break the cycle and provide you with the resources, education, and support needed to thrive.
<h2>Prevent: Safeguarding Stability Before the Storm Hits</h2>
<h3>Emergency Financial Assistance</h3>
If you''re on the brink of homelessness, every penny counts. Our <strong>Emergency Financial Assistance</strong> program can be a lifeline. Whether it''s rent that''s due or a medical bill that can''t wait, we provide immediate financial help.

<a href="https://www.example.com/apply-financial-aid">Apply for Immediate Financial Aid</a>
<h3>Long-term Solutions: Job Training Programs</h3>
Preventing homelessness isn''t just about immediate help; it''s about creating a stable future. Our <strong>Job Training Programs</strong> equip you with the skills you need for long-term employment.

<a href="https://www.example.com/job-training">Enroll in Skill-Building Courses</a>
<h2>Survive: Immediate Aid for the Most Vulnerable</h2>
<h3>Shelter Locator</h3>
If you find yourself without a home, your immediate concern is finding a safe place to stay. Our <strong>Shelter Locator</strong> helps you do just that.

<a href="https://www.homelessshelterdirectory.org/">Find a Shelter Near You</a>
<h3>Food and Clothing Drives</h3>
Being homeless is hard enough; worrying about your next meal shouldn''t be an added burden. Our <strong>Food and Clothing Drives</strong> provide essential supplies to help you survive.

<a href="https://www.example.com/food-clothing-drives">Locate Essential Supplies</a>
<h2>Thrive: Building a Sustainable Future</h2>
<h3>Permanent Housing Solutions</h3>
Finding a place to call home is the first step in building a stable future. Our <strong>Permanent Housing Solutions</strong> program helps you do just that.

<a href="https://www.hud.gov/topics/housing_choice_voucher_program_section_8">Explore Housing Options</a>
<h3>Job Training Programs</h3>
Stability requires more than just housing; it requires a reliable income. Our <strong>Job Training Programs</strong> offer courses in various fields to help you become employable and financially stable.

<a href="https://www.example.com/job-training">Enroll in Skill-Building Courses</a>
<h3>Financial Planning and Health Services</h3>
To truly thrive, you need to manage your finances wisely and take care of your health. Our <strong>Financial Planning and Health Services</strong> offer free consultations to set you on the path to a secure and healthy life.

<a href="https://www.example.com/financial-health-services">Book a Free Consultation</a>

For more information, feel free to <a href="mailto:info@luthascenterforexcellence.org">contact us</a>. Your journey from risk to recovery starts here, and we''re with you every step of the way.
<h2>Testimonials:</h2>
<blockquote>“HavenCycle helped me when I thought all hope was lost. Now, I have a job and a home. They saved my life.”

<em>- John D.</em></blockquote>
<blockquote>“They don’t just give you a fish; they teach you how to fish. HavenCycle set me on the path to stability.”

<em>- Emily S.</em></blockquote>
<h2>Inspirational Quotes from Successful Americans Who Overcame Homelessness:</h2>
<blockquote>"Don''t let your past dictate who you are, but let it be part of who you will become."

<em>- Tyler Perry, an American actor, director, and playwright who once lived in his car.</em></blockquote>
<blockquote>"Success is not built on success. It''s built on failure. It''s built on frustration. Sometimes it''s built on catastrophe."

<em>- Sumner Redstone, an American businessman who experienced homelessness and became a media magnate.</em></blockquote>
<blockquote>"I took a leap of faith, followed my dreams and paved my own path to success."

<em>- John Paul DeJoria, an entrepreneur who was once homeless and later co-founded Paul Mitchell.</em></blockquote>
<blockquote>"The biggest risk is not taking any risk. In a world that''s changing quickly, the only strategy that is guaranteed to fail is not taking risks."

<em>- Chris Gardner, whose life story was adapted into the movie "The Pursuit of Happyness."</em></blockquote>
For more information, feel free to <a href="mailto:info@luthascenterforexcellence.org">contact us</a>. Your journey from risk to recovery starts here, and we''re with you every step of the way.', '“Queens of STEM” – specifically designed to promote Science, Technology, Engineering, and Math for underprivileged single mothers, women, and young ladies. The first online school – curated to encourage growth, learning, and participation for underprivileged women and mothers', 'publish'::public.post_status, 1, 6628, NULL, '/homeless-prevention/', '/blog/homeless-prevention', '2023-04-19 07:43:43'::timestamptz, '2023-09-19 19:24:46'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17352, 'da-big-homie', 'Da Big Homie', '', 'Wisdom through Experience. Sharing life''s lessons and blessings with the younger generation.', 'publish'::public.post_status, 1, 17466, NULL, '/da-big-homie/', '/blog/da-big-homie', '2023-04-19 07:43:43'::timestamptz, '2023-11-02 16:14:17'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17353, 'queens-of-s-t-e-m', 'Queens of S.T.E.M', '<!-- Queens of STEM: Introduction -->
<h1>Queens of STEM: Empowering Underprivileged Women and Mothers in Science, Technology, Engineering, and Math</h1>
<!-- Introduction Section -->
<h2>Introduction</h2>
Welcome to the "Queens of STEM" program, an initiative by the Luthas Center for Excellence aimed at empowering underprivileged single mothers, women, and young ladies.

<!-- Why Queens of STEM? -->
<h2>Why Queens of STEM?</h2>
Only <strong>28%</strong> of women are in STEM careers, and less than <strong>10%</strong> of these women come from underprivileged backgrounds.

<!-- Expert Opinion from Harvard -->
<blockquote>According to <a href="https://hcwc.college.harvard.edu/get-involved/mentorship/wistem" target="_blank" rel="noopener">Harvard''s Women in Science and Engineering (WiSE)</a>, mentorship and community support are crucial for women in STEM.</blockquote>
<!-- Program Features -->
<h2>Program Features</h2>
<ul>
 	<li>Core Subjects: Science, Technology, Engineering, Math</li>
 	<li>Additional Courses: Soft Skills, Entrepreneurship, Financial Literacy</li>
</ul>
<!-- Expert Opinion from Columbia -->
<blockquote>Columbia University''s <a href="https://sps.columbia.edu/ideas-impact/columbia-youth-stem-initiative" target="_blank" rel="noopener">Youth STEM Initiative</a> highlights the importance of a well-rounded curriculum.</blockquote>
<!-- How to Enroll -->
<h2>How to Enroll</h2>
Women aged 18 and above with demonstrated financial need are eligible to apply.

<!-- Scholarships -->
<h3>Scholarships</h3>
We offer a range of scholarships to ensure that financial constraints are not a barrier to education.

<!-- Expert Opinion from Spelman -->
<blockquote>Spelman College emphasizes the importance of financial support and data-driven approaches for women in STEM. <a href="https://www.spelman.edu/about-us/news-and-events/news-releases/2022/10/24/google.org-grant-will-support-spelman-project-to-capture-critical-data-of-women-of-color-in-stem" target="_blank" rel="noopener">Read more</a>.</blockquote>
<!-- Conclusion -->
<h2>Conclusion</h2>
Don''t let barriers hold you back. Join the "Queens of STEM" program today and take the first step towards a brighter, more empowered future.

<!-- Contact Information -->
<h3>Contact Information</h3>
For more information, please email us at <a href="mailto:info@luthascenterforexcellence.org">info@luthascenterforexcellence.org</a> or call us at (646) 926-0213.

<!-- Embed Pew Research Graphs -->
<h3>Statistics and Graphs</h3>

<img src="https://www.pewresearch.org/science/wp-content/uploads/sites/16/2021/03/PS_2021.04.01_diversity-in-STEM_00-04.png?w=539" alt="Graph 1: Gender Diversity in STEM">
<img src="https://www.pewresearch.org/science/wp-content/uploads/sites/16/2021/03/PS_2021.04.01_diversity-in-STEM_00-03.png?w=428" alt="Graph 2: Racial Diversity in STEM">
<img src="https://www.pewresearch.org/science/wp-content/uploads/sites/16/2021/03/PS_2021.04.01_diversity-in-STEM_00-06.png?w=640" alt="Graph 3: Ethnic Diversity in STEM">
<img src="https://www.pewresearch.org/science/wp-content/uploads/sites/16/2021/03/PS_2021.04.01_diversity-in-STEM_00-05.png?w=620" alt="Graph 4: Age Diversity in STEM">', 'Empower underprivileged women and mothers with the Queens of STEM program by the Luthas Center for Excellence. Offering online courses in Science, Technology, Engineering, and Math, this initiative aims to bridge the gender and socio-economic gap in STEM fields', 'publish'::public.post_status, 1, 17469, NULL, '/queens-of-s-t-e-m/', '/blog/queens-of-s-t-e-m', '2023-04-19 07:43:43'::timestamptz, '2023-09-19 22:40:59'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17354, 'prenatal-death-prevention', 'Prenatal Death prevention', ' ', 'Programs designed to eliminate prenatal and early childhood deaths. No parent should ever bury their child.', 'publish'::public.post_status, 1, 6662, NULL, '/prenatal-death-prevention/', '/blog/prenatal-death-prevention', '2023-04-19 07:43:43'::timestamptz, '2023-04-19 07:43:43'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17855, 'black-investor-offers-7-billion-to-buy-washington-commanders', 'Black Investor Offers $7 Billion to Buy Washington Commanders', '<div class="post-body entry-content" id="post-body">
<center><a rel="nofollow noopener" target="_blank" href="/wp-content/uploads/2023/09/Black-Investor-Offers-7-Billion-to-Buy-Washington-Commanders.jpg"><img alt="Brian Davis" border="0" height="315" src="/placeholder-cover.svg" width="600"></a></center>
<p>
Brian Davis, an African American investor from the Washington DC area, has countered Magic Johnson''s group''s bid to buy the NFL''s Washington Commanders for $6 billion. He has reportedly submitted a solo bid to buy the team for $7 billion.</p><a rel="nofollow noopener" target="_blank" name="more"></a>Davis is the founder of Urban Echo Energy LLC, a Black-owned LEED-certified developer of renewable energy assets, and was previously a minority owner of DC United, a major league soccer team. He also played college basketball at Duke University and went on to play for the NBA''s Minnesota Timberwolves in the early 90s. <p>
According to <a rel="nofollow noopener" target="_blank" href="https://www.wusa9.com/article/sports/nfl/washington-commanders/washington-commanders-sale-offer-duke-basketball-player-brian-davis-7-billion-dollars/65-09092802-78a9-48c6-a07b-c021415dad3a" style="text-decoration: underline;">WUSA9</a>, Davis is offering to pay the first $1 billion to Dan Snyder, the team''s current owner, within 24 hours, and $6 billion within seven days. He says that he raised the capital by selling his own intellectual property which is reportedly worth $50 billion.
</p><p>
Bank of America, which is handling the sale, is reportedly still in communication with Davis about the deal. Nothing yet has been finalized, but if the deal goes through, Davis would become the first ever Black majority owner in the NFL. </p><p></p><p></p>
</div>', '', 'publish'::public.post_status, 1, 17858, NULL, '/black-investor-offers-7-billion-to-buy-washington-commanders/', '/blog/black-investor-offers-7-billion-to-buy-washington-commanders', '2023-04-17 05:05:00'::timestamptz, '2023-09-16 19:51:55'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (17268, 'get-a-one-year-sams-club-membership-for-10-right-now', 'Get a One-Year Sam''s Club Membership for $10 Right Now', 'For <a href="https://www.samsclub.com/">Sam’s Club</a>’s 40th birthday, they’re offering deals for both tiers of their memberships for a limited time. You can get the basic the<a href="https://www.samsclub.com/join/club?couponId=D68T4"> Club membership for $10</a> (usually $50) and the<a href="https://www.samsclub.com/join/plus?couponId=2M2WN"> Plus membership for $60</a> (usually $110).
<h2><b>How to get a discounted Sam’s Club membership</b></h2>
Simply follow the links above and the coupons will be automatically applied at checkout. If the coupons aren’t applied automatically, use promo code “D68T4" for the Club membership and “2M2WN” for the Plus membership at checkout. If you’re curious about the difference in the tiers, you can see a<a href="https://www.samsclub.com/join?pageName=aboutSams#:~:text=Instant%20Savings%20%2D%20get%20additional%20offers,on%20fuel%20at%20select%20clubs."> full breakdown here</a>.

Keep in mind that these deals are for “new members,” but some forums mention being able to use the same email again after a year of inactivity, or by just using a different email account.

The Club offer is valid until April 19, and the Plus offer will expire on April 30. Keep in mind that the membership auto-renews after the year, so if you don’t want to pay for the full price for another year, mark the date on your calendar to cancel.
<h2><b>BJ’s is also having a membership sale</b></h2>
If you don’t have a Sam’s Club within driving distance, see if you have a BJ’s close by. You can get their usual $55 yearly membership<a href="https://www.bjs.com/membership/clubCardEnroll?storeId=&amp;marketCode=JCCH24"> for $25 with this deal</a>.', '', 'publish'::public.post_status, 1, 17269, NULL, '/get-a-one-year-sams-club-membership-for-10-right-now/', '/blog/get-a-one-year-sams-club-membership-for-10-right-now', '2023-04-14 03:50:22'::timestamptz, '2023-04-14 04:09:37'::timestamptz) ON CONFLICT (wp_id) DO UPDATE SET slug = EXCLUDED.slug, title = EXCLUDED.title, content = EXCLUDED.content, excerpt = EXCLUDED.excerpt, status = EXCLUDED.status, author_id = EXCLUDED.author_id, featured_image_id = EXCLUDED.featured_image_id, reading_time = EXCLUDED.reading_time, old_path = EXCLUDED.old_path, new_path = EXCLUDED.new_path, published_at = EXCLUDED.published_at, modified_at = EXCLUDED.modified_at;
INSERT INTO public.posts (wp_id, slug, title, content, excerpt, status, author_id, featured_image_id, reading_time, old_path, new_path, published_at, modified_at) VALUES (4068, 'inspirational-quotes-to-keep-you-motivated-for-life-success', 'Inspirational Quotes To Keep You Motivated For Life Success', '
<p>Inspirational quotes can help motivate us and create a positive outlook on life and work when we need it most. They do so by harnessing the power of positive thinking. Reframing our brains to think positively is a key step in leading a happy and successful life.</p>



<p>You make a choice when you decide how you will react to any given situation. If you’re choosing (sometimes subconsciously) to complain and think negatively, your natural reaction will be to dwell on the negatives of every situation.</p>



<p>When you actively choose to think positively, regardless of how absolutely ridiculous it may seem, you will turn the situation into a development plan for growth, helping you become a better problem-solver and leader. Over time and after reframing your mind to think positively about problems, you’ll feel motivated, inspired, and empowered to take on any challenge that comes your way!</p>



<p>While reading through this list of the best motivational quotes in english, I recommend writing down some of the best inspirational and motivational quotes that resonate with you and your current situation. After writing them down, find the most motivational thought or the most inspiring passage, read it out loud, and then really try to understand the meaning.</p>



<p>You may find these inspirational quotes may come in handy when you’re having a hard day and need a little extra encouragement a and motivational line! So read these, write some down, and refer to them often.</p>



<h2>Inspirational Quotes</h2>



<p>The power of positive thinking is remarkable. When you think of something that brings you joy, your brain actually releases endorphins. Those endorphins fill you with the feeling of well-being.</p>



<p>Positive thinking helps you frame your mindset and change your life.</p>



<p>But when we feel down, it’s often difficult to conjure up things that make us happy. That’s why having some positive inspirational quotes or a motivated line on hand can be helpful in situations like that.</p>



<p>From short inspirational quotes and widely relatable anecdotes to motivational quotes specifically about work and life in general, here is a list of some of my favorite inspirational quotes.</p>



<h2>Inspirational Quotes for Your Personal Life</h2>



<p>“People tell you the world looks a certain way. Parents tell you how to think. Schools tell you how to think. TV. Religion. And then at a certain point, if you’re lucky, you realize you can make up your own mind. Nobody sets the rules but you. You can design your own life.”— Carrie Ann Moss</p>



<p>“Some women choose to follow men, and some choose to follow their dreams. If you’re wondering which way to go, remember that your career will never wake up and tell you that it doesn’t love you anymore.” — Lady Gaga</p>



<p>“Life is what happens to us while we are making other plans.”― Allen Saunders</p>



<p>“Life isn’t about finding yourself. Life is about creating yourself.”― George Bernard Shaw</p>



<p>“You are the sum total of everything you’ve ever seen, heard, eaten, smelled, been told, forgot ― it’s all there. Everything influences each of us, and because of that I try to make sure that my experiences are positive.” ― Maya Angelou</p>



<h2>Inspirational Quotes for Positive Thinking</h2>



<p>“Doubt kills more dreams than failure ever will.” – Suzy Kassem</p>



<p>“Keep your face always toward the sunshine, and shadows will fall behind you.” – Walt Whitman</p>



<p>“Whether you think you can or think you can’t, you’re right.” – Henry Ford</p>



<p>“Your talent determines what you can do. Your motivation determines how much you’re willing to do. Your attitude determines how well you do it.” —Lou Holtz</p>



<p>“The happiness of your life depends on the quality of your thoughts.” – Marcus Aurelius</p>



<h2>Inspirational Quotes for a Happy Life</h2>



<p>“You are who you are meant to be. Dance as if no one’s watching. Love as if it’s all you know. Dream as if you’ll live forever. Live as if you’ll die today.” James Dean</p>



<p>“You do not find the happy life. You make it.”— Camilla Eyring Kimball</p>



<p>“You’ve gotta dance like there’s nobody watching, Love like you’ll never be hurt, Sing like there’s nobody listening, And live like it’s heaven on earth.”― William W. Purkey</p>



<p>“Happiness is not something readymade. It comes from your own actions.”-Dalai Lama</p>



<p>“Folks are usually about as happy as they make up their minds to be.” – Abraham Lincoln</p>



<h2>Inspirational Quotes for the Darkest Moments</h2>



<p>“It is during our darkest moments that we must focus to see the light.” — Aristotle</p>



<p>“Develop success from failures. Discouragement and failure are two of the surest stepping stones to success.” -Dale Carnegie</p>



<p>“You learn more from failure than from success. Don’t let it stop you. Failure builds character.” — Unknown</p>



<p>“Fairytales do not tell children that dragons exist. Children already know that dragons exist. Fairytales tell children that dragons can be killed.” – G K Chesterton</p>



<p>“The bad news is time flies. The good news is you’re the pilot.” – Michael Altshuler</p>



<h2>Inspirational Quotes From Fairy Tales</h2>



<p>“Just because it’s what’s done doesn’t mean it’s what should be done!”- Cinderella</p>



<p>“With a smile and a song, life is just like a bright sunny day. Your cares fade away.” – Snow White</p>



<p>“It’s no use going back to yesterday because I was a different person then.” – Alice, Alice In Wonderland</p>



<p>“When we get to the end of the story, you will know more than you do now…” – Hans Christian Andersen, The Snow Queen</p>



<p>“The most important thing in life is to stop saying ‘I wish’ and start saying ‘I will’. Consider nothing impossible then treat possibilities as probabilities.” -Charles Dickens</p>



<h2>Inspirational Quotes for Taking a Difficult Risk</h2>



<p>“Learn as if you will live forever, live like you will die tomorrow.” — Mahatma Gandhi</p>



<p>“It is only when we take chances, when our lives improve. The initial and the most difficult risk that we need to take is to become honest. —Walter Anderson</p>



<p>“All our dreams can come true if we have the courage to pursue them.”- Walt Disney</p>



<p>“Move out of your comfort zone. You can only grow if you are willing to feel awkward and uncomfortable when you try something new.”- Brian Tracy</p>



<p>“Everything you’ve ever wanted is on the other side of fear.”- George Addair</p>



<h2>Inspirational Quotes to Build Confidence</h2>



<p>“Never bend your head. Always hold it high. Look the world straight in the eye.”– Helen Keller</p>



<p>“We generate fears while we sit. We overcome them by action. Fear is nature’s way of warning us to get busy.” –&nbsp; Dr. Henry Link</p>



<p>“The man who has confidence in himself gains the confidence of others.” – Hasidic Proverb</p>



<p>“What you lack in talent can be made up with desire, hustle and giving 110% all the time.” – Don Zimmer</p>



<p>“Fake it until you make it! Act as if you had all the confidence you require until it becomes your reality.” – Brian Tracy</p>



<h2>Inspirational Quotes to Help You Catch Excellence</h2>



<p>“Perfection is not attainable, but if we chase perfection we can catch excellence.”— Vince Lombardi</p>



<p>“Let us make our future now, and let us make our dreams tomorrow’s reality.” –&nbsp; Malala Yousafzai</p>



<p>“The best way to get started is to quit talking and begin doing.” ― Walt Disney</p>



<p>“Leaders set high standards. Refuse to tolerate mediocrity or poor performance.” – Brian Tracy</p>



<p>“It’s not whether you get knocked down, it’s whether you get back up.” –Vince Lombardi</p>



<h2>Inspirational Quotes to Overcome Bad News</h2>



<p>When one door closes, sometimes we need to turn the knob to open another… –&nbsp; J.A. Tran</p>



<p>“I can’t change the direction of the wind, but I can adjust my sails to always reach my destination.” – Jimmy Dean</p>



<p>“Don’t Let Yesterday Take Up Too Much Of Today.” – Will Rogers</p>



<p>“We may encounter many defeats but we must not be defeated.” – Maya Angelou</p>



